(()=>{const added=[{"id":"daily-2026-10-24-r01-q01","module":"Git","type":"概念题","title":"rebase 与 cherry-pick 的历史变化：关键机制","prompt":"请解释rebase 与 cherry-pick 的历史变化的关键机制和适用边界。","promptMarkdown":"请解释rebase 与 cherry-pick 的历史变化的关键机制和适用边界。","answer":["rebase 通常把一组提交重放到新基底，cherry-pick 选择指定提交应用到当前分支；新提交父链变化，提交 ID 通常也改变。"],"pitfalls":["父提交或元数据变化会产生新对象；内容类似不等于同一提交。"],"follow":"已共享分支被变基后同事拉取困难怎么办？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-24","sourceRound":1,"sourceQuestion":1,"sourceRoundTitle":"rebase 与 cherry-pick 的历史变化","referenceUrl":"https://git-scm.com/docs","answerMarkdown":"### 参考答案\nrebase 通常把一组提交重放到新基底，cherry-pick 选择指定提交应用到当前分支；新提交父链变化，提交 ID 通常也改变。\n\n### 易错点\n父提交或元数据变化会产生新对象；内容类似不等于同一提交。\n\n### 继续追问\n已共享分支被变基后同事拉取困难怎么办？"},{"id":"daily-2026-10-24-r01-q02","module":"Git","type":"概念题","title":"cherry-pick 后提交 ID 必须与原来相同吗？","prompt":"cherry-pick 后提交 ID 必须与原来相同吗？","promptMarkdown":"cherry-pick 后提交 ID 必须与原来相同吗？","answer":["父提交或元数据变化会产生新对象；内容类似不等于同一提交。"],"pitfalls":["父提交或元数据变化会产生新对象；内容类似不等于同一提交。"],"follow":"已共享分支被变基后同事拉取困难怎么办？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-24","sourceRound":1,"sourceQuestion":2,"sourceRoundTitle":"rebase 与 cherry-pick 的历史变化","referenceUrl":"https://git-scm.com/docs","answerMarkdown":"### 参考答案\n父提交或元数据变化会产生新对象；内容类似不等于同一提交。\n\n### 易错点\n父提交或元数据变化会产生新对象；内容类似不等于同一提交。\n\n### 继续追问\n已共享分支被变基后同事拉取困难怎么办？"},{"id":"daily-2026-10-24-r01-q03","module":"Git","type":"场景题","title":"已共享分支被变基后同事拉取困难怎么办？","prompt":"已共享分支被变基后同事拉取困难怎么办？","promptMarkdown":"已共享分支被变基后同事拉取困难怎么办？","answer":["先识别旧新基底和未共享工作，按团队约定协调恢复；避免直接强推覆盖他人提交。"],"pitfalls":["父提交或元数据变化会产生新对象；内容类似不等于同一提交。"],"follow":"已共享分支被变基后同事拉取困难怎么办？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-24","sourceRound":1,"sourceQuestion":3,"sourceRoundTitle":"rebase 与 cherry-pick 的历史变化","referenceUrl":"https://git-scm.com/docs","answerMarkdown":"### 参考答案\n先识别旧新基底和未共享工作，按团队约定协调恢复；避免直接强推覆盖他人提交。\n\n### 易错点\n父提交或元数据变化会产生新对象；内容类似不等于同一提交。\n\n### 继续追问\n已共享分支被变基后同事拉取困难怎么办？"},{"id":"daily-2026-10-24-r01-q04","module":"Git","type":"代码题","title":"rebase 与 cherry-pick 的历史变化：动手练习","prompt":"只读查看候选提交与当前分支，练习重放仅在临时分支进行。","promptMarkdown":"只读查看候选提交与当前分支，练习重放仅在临时分支进行。","answer":["rebase 通常把一组提交重放到新基底，cherry-pick 选择指定提交应用到当前分支；新提交父链变化，提交 ID 通常也改变。"],"pitfalls":["父提交或元数据变化会产生新对象；内容类似不等于同一提交。"],"follow":"已共享分支被变基后同事拉取困难怎么办？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-24","sourceRound":1,"sourceQuestion":4,"sourceRoundTitle":"rebase 与 cherry-pick 的历史变化","referenceUrl":"https://git-scm.com/docs","answerMarkdown":"### 参考答案\nrebase 通常把一组提交重放到新基底，cherry-pick 选择指定提交应用到当前分支；新提交父链变化，提交 ID 通常也改变。\n\n### 易错点\n父提交或元数据变化会产生新对象；内容类似不等于同一提交。\n\n### 示例\n```bash\ngit show --stat candidate_commit\ngit log --oneline --graph --decorate -10\n# 临时分支中：git cherry-pick candidate_commit\n```\n\n命令与配置用于隔离练习环境；先核对占位名称、权限、路径与工具版本。Docker 示例不代表已在你的服务中部署。\n\n### 继续追问\n已共享分支被变基后同事拉取困难怎么办？"},{"id":"daily-2026-10-24-r01-q05","module":"Git","type":"场景题","title":"IM 热修复需要移到发布分支，如何判断能否直接挑选？","prompt":"IM 热修复需要移到发布分支，如何判断能否直接挑选？","promptMarkdown":"IM 热修复需要移到发布分支，如何判断能否直接挑选？","answer":["检查依赖提交、配置和数据库兼容，挑选后验证目标分支；成功应用补丁不代表依赖完整。"],"pitfalls":["父提交或元数据变化会产生新对象；内容类似不等于同一提交。"],"follow":"已共享分支被变基后同事拉取困难怎么办？","manual":true,"priority":false,"project":"IM","sourceDate":"2026-10-24","sourceRound":1,"sourceQuestion":5,"sourceRoundTitle":"rebase 与 cherry-pick 的历史变化","referenceUrl":"https://git-scm.com/docs","answerMarkdown":"### 参考答案\n检查依赖提交、配置和数据库兼容，挑选后验证目标分支；成功应用补丁不代表依赖完整。\n\n### 易错点\n父提交或元数据变化会产生新对象；内容类似不等于同一提交。\n\n### 继续追问\n已共享分支被变基后同事拉取困难怎么办？"},{"id":"daily-2026-10-24-r02-q01","module":"Docker","type":"概念题","title":"Compose 依赖顺序与健康检查：关键机制","prompt":"请解释Compose 依赖顺序与健康检查的关键机制和适用边界。","promptMarkdown":"请解释Compose 依赖顺序与健康检查的关键机制和适用边界。","answer":["depends_on 可表达依赖顺序，普通启动并不保证依赖已可用。service_healthy 可等待健康条件，运行中的应用仍需处理依赖短暂故障。"],"pitfalls":["进程可能尚在初始化，健康检查也需覆盖真实就绪条件，不能只看容器状态。"],"follow":"Compose 首次启动应用经常连接失败，二次启动正常怎么办？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-24","sourceRound":2,"sourceQuestion":1,"sourceRoundTitle":"Compose 依赖顺序与健康检查","referenceUrl":"https://docs.docker.com/","answerMarkdown":"### 参考答案\ndepends_on 可表达依赖顺序，普通启动并不保证依赖已可用。service_healthy 可等待健康条件，运行中的应用仍需处理依赖短暂故障。\n\n### 易错点\n进程可能尚在初始化，健康检查也需覆盖真实就绪条件，不能只看容器状态。\n\n### 继续追问\nCompose 首次启动应用经常连接失败，二次启动正常怎么办？"},{"id":"daily-2026-10-24-r02-q02","module":"Docker","type":"概念题","title":"数据库容器 running 就能马上执行 SQL 吗？","prompt":"数据库容器 running 就能马上执行 SQL 吗？","promptMarkdown":"数据库容器 running 就能马上执行 SQL 吗？","answer":["进程可能尚在初始化，健康检查也需覆盖真实就绪条件，不能只看容器状态。"],"pitfalls":["进程可能尚在初始化，健康检查也需覆盖真实就绪条件，不能只看容器状态。"],"follow":"Compose 首次启动应用经常连接失败，二次启动正常怎么办？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-24","sourceRound":2,"sourceQuestion":2,"sourceRoundTitle":"Compose 依赖顺序与健康检查","referenceUrl":"https://docs.docker.com/","answerMarkdown":"### 参考答案\n进程可能尚在初始化，健康检查也需覆盖真实就绪条件，不能只看容器状态。\n\n### 易错点\n进程可能尚在初始化，健康检查也需覆盖真实就绪条件，不能只看容器状态。\n\n### 继续追问\nCompose 首次启动应用经常连接失败，二次启动正常怎么办？"},{"id":"daily-2026-10-24-r02-q03","module":"Docker","type":"场景题","title":"Compose 首次启动应用经常连接失败，二次启动正常怎么办？","prompt":"Compose 首次启动应用经常连接失败，二次启动正常怎么办？","promptMarkdown":"Compose 首次启动应用经常连接失败，二次启动正常怎么办？","answer":["核对数据库初始化和健康检查，再加有预算的连接重试；固定 sleep 无法证明就绪。"],"pitfalls":["进程可能尚在初始化，健康检查也需覆盖真实就绪条件，不能只看容器状态。"],"follow":"Compose 首次启动应用经常连接失败，二次启动正常怎么办？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-24","sourceRound":2,"sourceQuestion":3,"sourceRoundTitle":"Compose 依赖顺序与健康检查","referenceUrl":"https://docs.docker.com/","answerMarkdown":"### 参考答案\n核对数据库初始化和健康检查，再加有预算的连接重试；固定 sleep 无法证明就绪。\n\n### 易错点\n进程可能尚在初始化，健康检查也需覆盖真实就绪条件，不能只看容器状态。\n\n### 继续追问\nCompose 首次启动应用经常连接失败，二次启动正常怎么办？"},{"id":"daily-2026-10-24-r02-q04","module":"Docker","type":"代码题","title":"Compose 依赖顺序与健康检查：动手练习","prompt":"阅读服务就绪依赖骨架，说明 db 健康检查必须另行定义。","promptMarkdown":"阅读服务就绪依赖骨架，说明 db 健康检查必须另行定义。","answer":["depends_on 可表达依赖顺序，普通启动并不保证依赖已可用。service_healthy 可等待健康条件，运行中的应用仍需处理依赖短暂故障。"],"pitfalls":["进程可能尚在初始化，健康检查也需覆盖真实就绪条件，不能只看容器状态。"],"follow":"Compose 首次启动应用经常连接失败，二次启动正常怎么办？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-24","sourceRound":2,"sourceQuestion":4,"sourceRoundTitle":"Compose 依赖顺序与健康检查","referenceUrl":"https://docs.docker.com/","answerMarkdown":"### 参考答案\ndepends_on 可表达依赖顺序，普通启动并不保证依赖已可用。service_healthy 可等待健康条件，运行中的应用仍需处理依赖短暂故障。\n\n### 易错点\n进程可能尚在初始化，健康检查也需覆盖真实就绪条件，不能只看容器状态。\n\n### 示例\n```yaml\nservices:\n  app:\n    image: lab-app:demo\n    depends_on:\n      db:\n        condition: service_healthy\n  db:\n    image: lab-db:demo\n    # 必须提供与实际数据库匹配的 healthcheck\n```\n\n命令与配置用于隔离练习环境；先核对占位名称、权限、路径与工具版本。Docker 示例不代表已在你的服务中部署。\n\n### 继续追问\nCompose 首次启动应用经常连接失败，二次启动正常怎么办？"},{"id":"daily-2026-10-24-r02-q05","module":"Docker","type":"场景题","title":"云盘 Redis 启动后又短暂不可用，depends_on 会自动修复业务吗？","prompt":"云盘 Redis 启动后又短暂不可用，depends_on 会自动修复业务吗？","promptMarkdown":"云盘 Redis 启动后又短暂不可用，depends_on 会自动修复业务吗？","answer":["依赖启动条件不能替代运行时错误分类、重连和明确失败响应；应测试依赖中断与恢复，而非只验证首次启动。"],"pitfalls":["进程可能尚在初始化，健康检查也需覆盖真实就绪条件，不能只看容器状态。"],"follow":"Compose 首次启动应用经常连接失败，二次启动正常怎么办？","manual":true,"priority":false,"project":"云盘","sourceDate":"2026-10-24","sourceRound":2,"sourceQuestion":5,"sourceRoundTitle":"Compose 依赖顺序与健康检查","referenceUrl":"https://docs.docker.com/","answerMarkdown":"### 参考答案\n依赖启动条件不能替代运行时错误分类、重连和明确失败响应；应测试依赖中断与恢复，而非只验证首次启动。\n\n### 易错点\n进程可能尚在初始化，健康检查也需覆盖真实就绪条件，不能只看容器状态。\n\n### 继续追问\nCompose 首次启动应用经常连接失败，二次启动正常怎么办？"},{"id":"daily-2026-10-24-r03-q01","module":"Linux","type":"概念题","title":"epoll ET 与读到 EAGAIN：关键机制","prompt":"请解释epoll ET 与读到 EAGAIN的关键机制和适用边界。","promptMarkdown":"请解释epoll ET 与读到 EAGAIN的关键机制和适用边界。","answer":["边沿触发只在就绪变化等条件下通知，非阻塞读取应循环到 EAGAIN；同时处理 EOF、EINTR 和真实错误，不能每次事件只读固定一次。"],"pitfalls":["剩余数据仍在缓冲而没有新边沿时可能停滞；需完成排空或明确重新调度机制。"],"follow":"连接有数据却长期不处理，怎样审查事件循环？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-24","sourceRound":3,"sourceQuestion":1,"sourceRoundTitle":"epoll ET 与读到 EAGAIN","referenceUrl":"https://man7.org/linux/man-pages/","answerMarkdown":"### 参考答案\n边沿触发只在就绪变化等条件下通知，非阻塞读取应循环到 EAGAIN；同时处理 EOF、EINTR 和真实错误，不能每次事件只读固定一次。\n\n### 易错点\n剩余数据仍在缓冲而没有新边沿时可能停滞；需完成排空或明确重新调度机制。\n\n### 继续追问\n连接有数据却长期不处理，怎样审查事件循环？"},{"id":"daily-2026-10-24-r03-q02","module":"Linux","type":"概念题","title":"ET 收到一次事件只 recv 一次也能保证再通知吗？","prompt":"ET 收到一次事件只 recv 一次也能保证再通知吗？","promptMarkdown":"ET 收到一次事件只 recv 一次也能保证再通知吗？","answer":["剩余数据仍在缓冲而没有新边沿时可能停滞；需完成排空或明确重新调度机制。"],"pitfalls":["剩余数据仍在缓冲而没有新边沿时可能停滞；需完成排空或明确重新调度机制。"],"follow":"连接有数据却长期不处理，怎样审查事件循环？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-24","sourceRound":3,"sourceQuestion":2,"sourceRoundTitle":"epoll ET 与读到 EAGAIN","referenceUrl":"https://man7.org/linux/man-pages/","answerMarkdown":"### 参考答案\n剩余数据仍在缓冲而没有新边沿时可能停滞；需完成排空或明确重新调度机制。\n\n### 易错点\n剩余数据仍在缓冲而没有新边沿时可能停滞；需完成排空或明确重新调度机制。\n\n### 继续追问\n连接有数据却长期不处理，怎样审查事件循环？"},{"id":"daily-2026-10-24-r03-q03","module":"Linux","type":"场景题","title":"连接有数据却长期不处理，怎样审查事件循环？","prompt":"连接有数据却长期不处理，怎样审查事件循环？","promptMarkdown":"连接有数据却长期不处理，怎样审查事件循环？","answer":["看 fd 非阻塞标志、读循环终止原因、事件注册和任务分发，避免把 EAGAIN 当连接关闭。"],"pitfalls":["剩余数据仍在缓冲而没有新边沿时可能停滞；需完成排空或明确重新调度机制。"],"follow":"连接有数据却长期不处理，怎样审查事件循环？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-24","sourceRound":3,"sourceQuestion":3,"sourceRoundTitle":"epoll ET 与读到 EAGAIN","referenceUrl":"https://man7.org/linux/man-pages/","answerMarkdown":"### 参考答案\n看 fd 非阻塞标志、读循环终止原因、事件注册和任务分发，避免把 EAGAIN 当连接关闭。\n\n### 易错点\n剩余数据仍在缓冲而没有新边沿时可能停滞；需完成排空或明确重新调度机制。\n\n### 继续追问\n连接有数据却长期不处理，怎样审查事件循环？"},{"id":"daily-2026-10-24-r03-q04","module":"Linux","type":"代码题","title":"epoll ET 与读到 EAGAIN：动手练习","prompt":"解释非阻塞读循环的四种返回分支，省略协议分帧实现。","promptMarkdown":"解释非阻塞读循环的四种返回分支，省略协议分帧实现。","answer":["边沿触发只在就绪变化等条件下通知，非阻塞读取应循环到 EAGAIN；同时处理 EOF、EINTR 和真实错误，不能每次事件只读固定一次。"],"pitfalls":["剩余数据仍在缓冲而没有新边沿时可能停滞；需完成排空或明确重新调度机制。"],"follow":"连接有数据却长期不处理，怎样审查事件循环？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-24","sourceRound":3,"sourceQuestion":4,"sourceRoundTitle":"epoll ET 与读到 EAGAIN","referenceUrl":"https://man7.org/linux/man-pages/","answerMarkdown":"### 参考答案\n边沿触发只在就绪变化等条件下通知，非阻塞读取应循环到 EAGAIN；同时处理 EOF、EINTR 和真实错误，不能每次事件只读固定一次。\n\n### 易错点\n剩余数据仍在缓冲而没有新边沿时可能停滞；需完成排空或明确重新调度机制。\n\n### 示例\n```c\nfor (;;) {\n    ssize_t n = recv(fd, buf, sizeof buf, 0);\n    if (n > 0) { /* 累积并解析 */ continue; }\n    if (n == 0) { /* EOF */ break; }\n    if (errno == EINTR) continue;\n    if (errno == EAGAIN || errno == EWOULDBLOCK) break;\n    /* 真正错误 */ break;\n}\n```\n\n命令与配置用于隔离练习环境；先核对占位名称、权限、路径与工具版本。Docker 示例不代表已在你的服务中部署。\n\n### 继续追问\n连接有数据却长期不处理，怎样审查事件循环？"},{"id":"daily-2026-10-24-r03-q05","module":"Linux","type":"场景题","title":"IM 用库管理 WebSocket 时，是否应另外接管库的 socket 读循环？","prompt":"IM 用库管理 WebSocket 时，是否应另外接管库的 socket 读循环？","promptMarkdown":"IM 用库管理 WebSocket 时，是否应另外接管库的 socket 读循环？","answer":["先明确底层库的所有权和回调契约，不能同时由两套逻辑消费同一流；练习底层机制不等于要绕过库实现。"],"pitfalls":["剩余数据仍在缓冲而没有新边沿时可能停滞；需完成排空或明确重新调度机制。"],"follow":"连接有数据却长期不处理，怎样审查事件循环？","manual":true,"priority":false,"project":"IM","sourceDate":"2026-10-24","sourceRound":3,"sourceQuestion":5,"sourceRoundTitle":"epoll ET 与读到 EAGAIN","referenceUrl":"https://man7.org/linux/man-pages/","answerMarkdown":"### 参考答案\n先明确底层库的所有权和回调契约，不能同时由两套逻辑消费同一流；练习底层机制不等于要绕过库实现。\n\n### 易错点\n剩余数据仍在缓冲而没有新边沿时可能停滞；需完成排空或明确重新调度机制。\n\n### 继续追问\n连接有数据却长期不处理，怎样审查事件循环？"},{"id":"daily-2026-10-24-r04-q01","module":"Linux","type":"概念题","title":"短写、EPIPE 与非阻塞发送：关键机制","prompt":"请解释短写、EPIPE 与非阻塞发送的关键机制和适用边界。","promptMarkdown":"请解释短写、EPIPE 与非阻塞发送的关键机制和适用边界。","answer":["write/send 成功可能只处理部分数据，非阻塞发送需维护剩余偏移并等待可写。对端关闭可能触发 EPIPE 与 SIGPIPE，处理策略要明确。"],"pitfalls":["应比较返回字节数与待发长度，且写入内核缓冲不等于对端应用确认。"],"follow":"大消息尾部丢失而小消息正常，如何排查？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-24","sourceRound":4,"sourceQuestion":1,"sourceRoundTitle":"短写、EPIPE 与非阻塞发送","referenceUrl":"https://man7.org/linux/man-pages/","answerMarkdown":"### 参考答案\nwrite/send 成功可能只处理部分数据，非阻塞发送需维护剩余偏移并等待可写。对端关闭可能触发 EPIPE 与 SIGPIPE，处理策略要明确。\n\n### 易错点\n应比较返回字节数与待发长度，且写入内核缓冲不等于对端应用确认。\n\n### 继续追问\n大消息尾部丢失而小消息正常，如何排查？"},{"id":"daily-2026-10-24-r04-q02","module":"Linux","type":"概念题","title":"send 返回正数就说明整个消息发完了吗？","prompt":"send 返回正数就说明整个消息发完了吗？","promptMarkdown":"send 返回正数就说明整个消息发完了吗？","answer":["应比较返回字节数与待发长度，且写入内核缓冲不等于对端应用确认。"],"pitfalls":["应比较返回字节数与待发长度，且写入内核缓冲不等于对端应用确认。"],"follow":"大消息尾部丢失而小消息正常，如何排查？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-24","sourceRound":4,"sourceQuestion":2,"sourceRoundTitle":"短写、EPIPE 与非阻塞发送","referenceUrl":"https://man7.org/linux/man-pages/","answerMarkdown":"### 参考答案\n应比较返回字节数与待发长度，且写入内核缓冲不等于对端应用确认。\n\n### 易错点\n应比较返回字节数与待发长度，且写入内核缓冲不等于对端应用确认。\n\n### 继续追问\n大消息尾部丢失而小消息正常，如何排查？"},{"id":"daily-2026-10-24-r04-q03","module":"Linux","type":"场景题","title":"大消息尾部丢失而小消息正常，如何排查？","prompt":"大消息尾部丢失而小消息正常，如何排查？","promptMarkdown":"大消息尾部丢失而小消息正常，如何排查？","answer":["核对短写处理、缓冲寿命和 EAGAIN 后偏移保存，检查是否错误重发整个缓冲。"],"pitfalls":["应比较返回字节数与待发长度，且写入内核缓冲不等于对端应用确认。"],"follow":"大消息尾部丢失而小消息正常，如何排查？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-24","sourceRound":4,"sourceQuestion":3,"sourceRoundTitle":"短写、EPIPE 与非阻塞发送","referenceUrl":"https://man7.org/linux/man-pages/","answerMarkdown":"### 参考答案\n核对短写处理、缓冲寿命和 EAGAIN 后偏移保存，检查是否错误重发整个缓冲。\n\n### 易错点\n应比较返回字节数与待发长度，且写入内核缓冲不等于对端应用确认。\n\n### 继续追问\n大消息尾部丢失而小消息正常，如何排查？"},{"id":"daily-2026-10-24-r04-q04","module":"Linux","type":"代码题","title":"短写、EPIPE 与非阻塞发送：动手练习","prompt":"用伪代码维护发送偏移，说明事件循环何时再注册可写。","promptMarkdown":"用伪代码维护发送偏移，说明事件循环何时再注册可写。","answer":["write/send 成功可能只处理部分数据，非阻塞发送需维护剩余偏移并等待可写。对端关闭可能触发 EPIPE 与 SIGPIPE，处理策略要明确。"],"pitfalls":["应比较返回字节数与待发长度，且写入内核缓冲不等于对端应用确认。"],"follow":"大消息尾部丢失而小消息正常，如何排查？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-24","sourceRound":4,"sourceQuestion":4,"sourceRoundTitle":"短写、EPIPE 与非阻塞发送","referenceUrl":"https://man7.org/linux/man-pages/","answerMarkdown":"### 参考答案\nwrite/send 成功可能只处理部分数据，非阻塞发送需维护剩余偏移并等待可写。对端关闭可能触发 EPIPE 与 SIGPIPE，处理策略要明确。\n\n### 易错点\n应比较返回字节数与待发长度，且写入内核缓冲不等于对端应用确认。\n\n### 示例\n```bash\n# offset += send 返回的正数字节数\n# EAGAIN：保留 buffer 和 offset，等待可写\n# 完成：移出队列，避免永久订阅可写造成忙循环\n```\n\n命令与配置用于隔离练习环境；先核对占位名称、权限、路径与工具版本。Docker 示例不代表已在你的服务中部署。\n\n### 继续追问\n大消息尾部丢失而小消息正常，如何排查？"},{"id":"daily-2026-10-24-r04-q05","module":"Linux","type":"场景题","title":"IM 发送队列为什么要拥有消息缓冲？","prompt":"IM 发送队列为什么要拥有消息缓冲？","promptMarkdown":"IM 发送队列为什么要拥有消息缓冲？","answer":["尚未完成的部分会跨事件循环轮次继续发送，必须保证缓冲存活且内容不被并发修改，同时限制队列总量。"],"pitfalls":["应比较返回字节数与待发长度，且写入内核缓冲不等于对端应用确认。"],"follow":"大消息尾部丢失而小消息正常，如何排查？","manual":true,"priority":false,"project":"IM","sourceDate":"2026-10-24","sourceRound":4,"sourceQuestion":5,"sourceRoundTitle":"短写、EPIPE 与非阻塞发送","referenceUrl":"https://man7.org/linux/man-pages/","answerMarkdown":"### 参考答案\n尚未完成的部分会跨事件循环轮次继续发送，必须保证缓冲存活且内容不被并发修改，同时限制队列总量。\n\n### 易错点\n应比较返回字节数与待发长度，且写入内核缓冲不等于对端应用确认。\n\n### 继续追问\n大消息尾部丢失而小消息正常，如何排查？"},{"id":"daily-2026-10-24-r05-q01","module":"Qt","type":"概念题","title":"QHttpMultiPart 与上传设备生命周期：关键机制","prompt":"请解释QHttpMultiPart 与上传设备生命周期的关键机制和适用边界。","promptMarkdown":"请解释QHttpMultiPart 与上传设备生命周期的关键机制和适用边界。","answer":["QHttpMultiPart 组织 multipart 正文，setBodyDevice 使用的 QFile 必须在异步上传期间保持打开和存活；可通过父子关系连接 file、multipart 与 reply 的寿命。"],"pitfalls":["请求异步读取设备，提前关闭或销毁会使上传失败；不能仅保证函数调用时文件存在。"],"follow":"上传随机失败且文件内容为空，怎么查？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-24","sourceRound":5,"sourceQuestion":1,"sourceRoundTitle":"QHttpMultiPart 与上传设备生命周期","referenceUrl":"https://doc.qt.io/qt-6/","answerMarkdown":"### 参考答案\nQHttpMultiPart 组织 multipart 正文，setBodyDevice 使用的 QFile 必须在异步上传期间保持打开和存活；可通过父子关系连接 file、multipart 与 reply 的寿命。\n\n### 易错点\n请求异步读取设备，提前关闭或销毁会使上传失败；不能仅保证函数调用时文件存在。\n\n### 继续追问\n上传随机失败且文件内容为空，怎么查？"},{"id":"daily-2026-10-24-r05-q02","module":"Qt","type":"概念题","title":"post 返回后立刻销毁 QFile 也能正常上传吗？","prompt":"post 返回后立刻销毁 QFile 也能正常上传吗？","promptMarkdown":"post 返回后立刻销毁 QFile 也能正常上传吗？","answer":["请求异步读取设备，提前关闭或销毁会使上传失败；不能仅保证函数调用时文件存在。"],"pitfalls":["请求异步读取设备，提前关闭或销毁会使上传失败；不能仅保证函数调用时文件存在。"],"follow":"上传随机失败且文件内容为空，怎么查？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-24","sourceRound":5,"sourceQuestion":2,"sourceRoundTitle":"QHttpMultiPart 与上传设备生命周期","referenceUrl":"https://doc.qt.io/qt-6/","answerMarkdown":"### 参考答案\n请求异步读取设备，提前关闭或销毁会使上传失败；不能仅保证函数调用时文件存在。\n\n### 易错点\n请求异步读取设备，提前关闭或销毁会使上传失败；不能仅保证函数调用时文件存在。\n\n### 继续追问\n上传随机失败且文件内容为空，怎么查？"},{"id":"daily-2026-10-24-r05-q03","module":"Qt","type":"场景题","title":"上传随机失败且文件内容为空，怎么查？","prompt":"上传随机失败且文件内容为空，怎么查？","promptMarkdown":"上传随机失败且文件内容为空，怎么查？","answer":["检查 QFile 打开结果、父对象和栈对象寿命、multipart boundary 与请求完成前是否销毁设备。"],"pitfalls":["请求异步读取设备，提前关闭或销毁会使上传失败；不能仅保证函数调用时文件存在。"],"follow":"上传随机失败且文件内容为空，怎么查？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-24","sourceRound":5,"sourceQuestion":3,"sourceRoundTitle":"QHttpMultiPart 与上传设备生命周期","referenceUrl":"https://doc.qt.io/qt-6/","answerMarkdown":"### 参考答案\n检查 QFile 打开结果、父对象和栈对象寿命、multipart boundary 与请求完成前是否销毁设备。\n\n### 易错点\n请求异步读取设备，提前关闭或销毁会使上传失败；不能仅保证函数调用时文件存在。\n\n### 继续追问\n上传随机失败且文件内容为空，怎么查？"},{"id":"daily-2026-10-24-r05-q04","module":"Qt","type":"代码题","title":"QHttpMultiPart 与上传设备生命周期：动手练习","prompt":"解释 multipart 绑定到 reply 的目的，文件打开失败必须提前结束。","promptMarkdown":"解释 multipart 绑定到 reply 的目的，文件打开失败必须提前结束。","answer":["QHttpMultiPart 组织 multipart 正文，setBodyDevice 使用的 QFile 必须在异步上传期间保持打开和存活；可通过父子关系连接 file、multipart 与 reply 的寿命。"],"pitfalls":["请求异步读取设备，提前关闭或销毁会使上传失败；不能仅保证函数调用时文件存在。"],"follow":"上传随机失败且文件内容为空，怎么查？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-24","sourceRound":5,"sourceQuestion":4,"sourceRoundTitle":"QHttpMultiPart 与上传设备生命周期","referenceUrl":"https://doc.qt.io/qt-6/","answerMarkdown":"### 参考答案\nQHttpMultiPart 组织 multipart 正文，setBodyDevice 使用的 QFile 必须在异步上传期间保持打开和存活；可通过父子关系连接 file、multipart 与 reply 的寿命。\n\n### 易错点\n请求异步读取设备，提前关闭或销毁会使上传失败；不能仅保证函数调用时文件存在。\n\n### 示例\n```cpp-qt\nauto *multi = new QHttpMultiPart(QHttpMultiPart::FormDataType);\nauto *file = new QFile(path, multi);\nif (!file->open(QIODevice::ReadOnly)) { delete multi; return; }\nQHttpPart part; // 补充 Content-Disposition 等头\npart.setBodyDevice(file); multi->append(part);\nauto *reply = manager->post(request, multi);\nmulti->setParent(reply);\n```\n\n命令与配置用于隔离练习环境；先核对占位名称、权限、路径与工具版本。Docker 示例不代表已在你的服务中部署。\n\n### 继续追问\n上传随机失败且文件内容为空，怎么查？"},{"id":"daily-2026-10-24-r05-q05","module":"Qt","type":"场景题","title":"云盘进度条到 100% 就能提示上传入库成功吗？","prompt":"云盘进度条到 100% 就能提示上传入库成功吗？","promptMarkdown":"云盘进度条到 100% 就能提示上传入库成功吗？","answer":["uploadProgress 反映发送进度，不代表服务端已完成存储与元数据提交；最终成功应以完成回调中的有效业务响应为准。"],"pitfalls":["请求异步读取设备，提前关闭或销毁会使上传失败；不能仅保证函数调用时文件存在。"],"follow":"上传随机失败且文件内容为空，怎么查？","manual":true,"priority":false,"project":"云盘","sourceDate":"2026-10-24","sourceRound":5,"sourceQuestion":5,"sourceRoundTitle":"QHttpMultiPart 与上传设备生命周期","referenceUrl":"https://doc.qt.io/qt-6/","answerMarkdown":"### 参考答案\nuploadProgress 反映发送进度，不代表服务端已完成存储与元数据提交；最终成功应以完成回调中的有效业务响应为准。\n\n### 易错点\n请求异步读取设备，提前关闭或销毁会使上传失败；不能仅保证函数调用时文件存在。\n\n### 继续追问\n上传随机失败且文件内容为空，怎么查？"},{"id":"daily-2026-10-24-r06-q01","module":"C++","type":"概念题","title":"variant 与显式状态建模：关键机制","prompt":"请解释variant 与显式状态建模的关键机制和适用边界。","promptMarkdown":"请解释variant 与显式状态建模的关键机制和适用边界。","answer":["variant 保存一组类型中的一个有效选项，visit 可按实际类型分派。用类型区分错误与成功，能减少多个布尔标记组成的非法状态。"],"pitfalls":["类型不匹配时会出错；应使用 get_if、holds_alternative 或 visit。"],"follow":"接口同时返回 success=true 和 error 字段，如何重构？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-24","sourceRound":6,"sourceQuestion":1,"sourceRoundTitle":"variant 与显式状态建模","referenceUrl":"https://eel.is/c++draft/","answerMarkdown":"### 参考答案\nvariant 保存一组类型中的一个有效选项，visit 可按实际类型分派。用类型区分错误与成功，能减少多个布尔标记组成的非法状态。\n\n### 易错点\n类型不匹配时会出错；应使用 get_if、holds_alternative 或 visit。\n\n### 继续追问\n接口同时返回 success=true 和 error 字段，如何重构？"},{"id":"daily-2026-10-24-r06-q02","module":"C++","type":"概念题","title":"variant 能用 get 读取任意备选类型吗？","prompt":"variant 能用 get 读取任意备选类型吗？","promptMarkdown":"variant 能用 get 读取任意备选类型吗？","answer":["类型不匹配时会出错；应使用 get_if、holds_alternative 或 visit。"],"pitfalls":["类型不匹配时会出错；应使用 get_if、holds_alternative 或 visit。"],"follow":"接口同时返回 success=true 和 error 字段，如何重构？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-24","sourceRound":6,"sourceQuestion":2,"sourceRoundTitle":"variant 与显式状态建模","referenceUrl":"https://eel.is/c++draft/","answerMarkdown":"### 参考答案\n类型不匹配时会出错；应使用 get_if、holds_alternative 或 visit。\n\n### 易错点\n类型不匹配时会出错；应使用 get_if、holds_alternative 或 visit。\n\n### 继续追问\n接口同时返回 success=true 和 error 字段，如何重构？"},{"id":"daily-2026-10-24-r06-q03","module":"C++","type":"场景题","title":"接口同时返回 success=true 和 error 字段，如何重构？","prompt":"接口同时返回 success=true 和 error 字段，如何重构？","promptMarkdown":"接口同时返回 success=true 和 error 字段，如何重构？","answer":["用互斥的成功/失败结果类型承载必要数据，并在边界统一转换为协议响应。"],"pitfalls":["类型不匹配时会出错；应使用 get_if、holds_alternative 或 visit。"],"follow":"接口同时返回 success=true 和 error 字段，如何重构？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-24","sourceRound":6,"sourceQuestion":3,"sourceRoundTitle":"variant 与显式状态建模","referenceUrl":"https://eel.is/c++draft/","answerMarkdown":"### 参考答案\n用互斥的成功/失败结果类型承载必要数据，并在边界统一转换为协议响应。\n\n### 易错点\n类型不匹配时会出错；应使用 get_if、holds_alternative 或 visit。\n\n### 继续追问\n接口同时返回 success=true 和 error 字段，如何重构？"},{"id":"daily-2026-10-24-r06-q04","module":"C++","type":"代码题","title":"variant 与显式状态建模：动手练习","prompt":"用 variant 表达整数结果或错误文本，并验证类型。","promptMarkdown":"用 variant 表达整数结果或错误文本，并验证类型。","answer":["variant 保存一组类型中的一个有效选项，visit 可按实际类型分派。用类型区分错误与成功，能减少多个布尔标记组成的非法状态。"],"pitfalls":["类型不匹配时会出错；应使用 get_if、holds_alternative 或 visit。"],"follow":"接口同时返回 success=true 和 error 字段，如何重构？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-24","sourceRound":6,"sourceQuestion":4,"sourceRoundTitle":"variant 与显式状态建模","referenceUrl":"https://eel.is/c++draft/","answerMarkdown":"### 参考答案\nvariant 保存一组类型中的一个有效选项，visit 可按实际类型分派。用类型区分错误与成功，能减少多个布尔标记组成的非法状态。\n\n### 易错点\n类型不匹配时会出错；应使用 get_if、holds_alternative 或 visit。\n\n### 示例\n```cpp\n#include <cassert>\n#include <string>\n#include <variant>\nint main(){std::variant<int,std::string> r=7;assert(std::get<int>(r)==7);r=std::string(\"error\");assert(std::holds_alternative<std::string>(r));}\n```\n\n此为独立 C++17 练习程序，验证记录见当日文件。\n\n### 继续追问\n接口同时返回 success=true 和 error 字段，如何重构？"},{"id":"daily-2026-10-24-r06-q05","module":"C++","type":"场景题","title":"云盘下载结果为什么不宜只用空字符串表示失败？","prompt":"云盘下载结果为什么不宜只用空字符串表示失败？","promptMarkdown":"云盘下载结果为什么不宜只用空字符串表示失败？","answer":["空文件和多类错误无法可靠区分，结果类型应携带状态、错误阶段和必要元信息，避免把正常空内容当成失败。"],"pitfalls":["类型不匹配时会出错；应使用 get_if、holds_alternative 或 visit。"],"follow":"接口同时返回 success=true 和 error 字段，如何重构？","manual":true,"priority":false,"project":"云盘","sourceDate":"2026-10-24","sourceRound":6,"sourceQuestion":5,"sourceRoundTitle":"variant 与显式状态建模","referenceUrl":"https://eel.is/c++draft/","answerMarkdown":"### 参考答案\n空文件和多类错误无法可靠区分，结果类型应携带状态、错误阶段和必要元信息，避免把正常空内容当成失败。\n\n### 易错点\n类型不匹配时会出错；应使用 get_if、holds_alternative 或 visit。\n\n### 继续追问\n接口同时返回 success=true 和 error 字段，如何重构？"},{"id":"daily-2026-10-24-r07-q01","module":"TCP/HTTP","type":"概念题","title":"HTTP 缓存验证与静态资源版本：关键机制","prompt":"请解释HTTP 缓存验证与静态资源版本的关键机制和适用边界。","promptMarkdown":"请解释HTTP 缓存验证与静态资源版本的关键机制和适用边界。","answer":["缓存可由新鲜度或条件请求决定复用，ETag 等验证器服务于表示版本。HTML 与脚本发布要考虑不同资源的缓存策略，避免混用版本。"],"pitfalls":["浏览器与中间缓存可能复用资源，离线服务工作线程也可能提供快照；要检查实际版本。"],"follow":"练习台部署成功但手机还是旧题，如何定位？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-24","sourceRound":7,"sourceQuestion":1,"sourceRoundTitle":"HTTP 缓存验证与静态资源版本","referenceUrl":"https://www.rfc-editor.org/rfc/rfc9110","answerMarkdown":"### 参考答案\n缓存可由新鲜度或条件请求决定复用，ETag 等验证器服务于表示版本。HTML 与脚本发布要考虑不同资源的缓存策略，避免混用版本。\n\n### 易错点\n浏览器与中间缓存可能复用资源，离线服务工作线程也可能提供快照；要检查实际版本。\n\n### 继续追问\n练习台部署成功但手机还是旧题，如何定位？"},{"id":"daily-2026-10-24-r07-q02","module":"TCP/HTTP","type":"概念题","title":"刷新页面一定从服务器重新下载全部脚本吗？","prompt":"刷新页面一定从服务器重新下载全部脚本吗？","promptMarkdown":"刷新页面一定从服务器重新下载全部脚本吗？","answer":["浏览器与中间缓存可能复用资源，离线服务工作线程也可能提供快照；要检查实际版本。"],"pitfalls":["浏览器与中间缓存可能复用资源，离线服务工作线程也可能提供快照；要检查实际版本。"],"follow":"练习台部署成功但手机还是旧题，如何定位？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-24","sourceRound":7,"sourceQuestion":2,"sourceRoundTitle":"HTTP 缓存验证与静态资源版本","referenceUrl":"https://www.rfc-editor.org/rfc/rfc9110","answerMarkdown":"### 参考答案\n浏览器与中间缓存可能复用资源，离线服务工作线程也可能提供快照；要检查实际版本。\n\n### 易错点\n浏览器与中间缓存可能复用资源，离线服务工作线程也可能提供快照；要检查实际版本。\n\n### 继续追问\n练习台部署成功但手机还是旧题，如何定位？"},{"id":"daily-2026-10-24-r07-q03","module":"TCP/HTTP","type":"场景题","title":"练习台部署成功但手机还是旧题，如何定位？","prompt":"练习台部署成功但手机还是旧题，如何定位？","promptMarkdown":"练习台部署成功但手机还是旧题，如何定位？","answer":["核对页面与脚本版本、响应缓存头和离线更新状态，先确认是否旧缓存，不重复发布相同内容。"],"pitfalls":["浏览器与中间缓存可能复用资源，离线服务工作线程也可能提供快照；要检查实际版本。"],"follow":"练习台部署成功但手机还是旧题，如何定位？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-24","sourceRound":7,"sourceQuestion":3,"sourceRoundTitle":"HTTP 缓存验证与静态资源版本","referenceUrl":"https://www.rfc-editor.org/rfc/rfc9110","answerMarkdown":"### 参考答案\n核对页面与脚本版本、响应缓存头和离线更新状态，先确认是否旧缓存，不重复发布相同内容。\n\n### 易错点\n浏览器与中间缓存可能复用资源，离线服务工作线程也可能提供快照；要检查实际版本。\n\n### 继续追问\n练习台部署成功但手机还是旧题，如何定位？"},{"id":"daily-2026-10-24-r07-q04","module":"TCP/HTTP","type":"代码题","title":"HTTP 缓存验证与静态资源版本：动手练习","prompt":"只读比较页面与脚本响应头，标明条件请求用途。","promptMarkdown":"只读比较页面与脚本响应头，标明条件请求用途。","answer":["缓存可由新鲜度或条件请求决定复用，ETag 等验证器服务于表示版本。HTML 与脚本发布要考虑不同资源的缓存策略，避免混用版本。"],"pitfalls":["浏览器与中间缓存可能复用资源，离线服务工作线程也可能提供快照；要检查实际版本。"],"follow":"练习台部署成功但手机还是旧题，如何定位？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-24","sourceRound":7,"sourceQuestion":4,"sourceRoundTitle":"HTTP 缓存验证与静态资源版本","referenceUrl":"https://www.rfc-editor.org/rfc/rfc9110","answerMarkdown":"### 参考答案\n缓存可由新鲜度或条件请求决定复用，ETag 等验证器服务于表示版本。HTML 与脚本发布要考虑不同资源的缓存策略，避免混用版本。\n\n### 易错点\n浏览器与中间缓存可能复用资源，离线服务工作线程也可能提供快照；要检查实际版本。\n\n### 示例\n```bash\ncurl -I https://example.com/index.html\ncurl -I https://example.com/app.js?v=release-2\n# 对实际测试资源观察 Cache-Control、ETag 与 Last-Modified\n```\n\n命令与配置用于隔离练习环境；先核对占位名称、权限、路径与工具版本。Docker 示例不代表已在你的服务中部署。\n\n### 继续追问\n练习台部署成功但手机还是旧题，如何定位？"},{"id":"daily-2026-10-24-r07-q05","module":"TCP/HTTP","type":"场景题","title":"IM 前端与后端字段同步升级，如何避免旧脚本不兼容？","prompt":"IM 前端与后端字段同步升级，如何避免旧脚本不兼容？","promptMarkdown":"IM 前端与后端字段同步升级，如何避免旧脚本不兼容？","answer":["保持协议兼容窗口或使用显式版本与整体发布策略，验证旧客户端行为，不能只依靠每个人手动清缓存。"],"pitfalls":["浏览器与中间缓存可能复用资源，离线服务工作线程也可能提供快照；要检查实际版本。"],"follow":"练习台部署成功但手机还是旧题，如何定位？","manual":true,"priority":false,"project":"IM","sourceDate":"2026-10-24","sourceRound":7,"sourceQuestion":5,"sourceRoundTitle":"HTTP 缓存验证与静态资源版本","referenceUrl":"https://www.rfc-editor.org/rfc/rfc9110","answerMarkdown":"### 参考答案\n保持协议兼容窗口或使用显式版本与整体发布策略，验证旧客户端行为，不能只依靠每个人手动清缓存。\n\n### 易错点\n浏览器与中间缓存可能复用资源，离线服务工作线程也可能提供快照；要检查实际版本。\n\n### 继续追问\n练习台部署成功但手机还是旧题，如何定位？"},{"id":"daily-2026-10-24-r08-q01","module":"MySQL","type":"概念题","title":"预处理语句与参数绑定：关键机制","prompt":"请解释预处理语句与参数绑定的关键机制和适用边界。","promptMarkdown":"请解释预处理语句与参数绑定的关键机制和适用边界。","answer":["预处理把 SQL 结构与参数值分开，绑定值不能改变 SQL 结构。表名、列名和排序方向通常不能作为普通参数绑定，应使用受控白名单。"],"pitfalls":["不能用参数任意绑定标识符；分页范围、排序选项和业务授权仍需验证。"],"follow":"搜索文件名包含引号时 SQL 失败，怎么修？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-24","sourceRound":8,"sourceQuestion":1,"sourceRoundTitle":"预处理语句与参数绑定","referenceUrl":"https://dev.mysql.com/doc/refman/8.4/en/","answerMarkdown":"### 参考答案\n预处理把 SQL 结构与参数值分开，绑定值不能改变 SQL 结构。表名、列名和排序方向通常不能作为普通参数绑定，应使用受控白名单。\n\n### 易错点\n不能用参数任意绑定标识符；分页范围、排序选项和业务授权仍需验证。\n\n### 继续追问\n搜索文件名包含引号时 SQL 失败，怎么修？"},{"id":"daily-2026-10-24-r08-q02","module":"MySQL","type":"概念题","title":"绑定参数能替代所有动态 SQL 校验吗？","prompt":"绑定参数能替代所有动态 SQL 校验吗？","promptMarkdown":"绑定参数能替代所有动态 SQL 校验吗？","answer":["不能用参数任意绑定标识符；分页范围、排序选项和业务授权仍需验证。"],"pitfalls":["不能用参数任意绑定标识符；分页范围、排序选项和业务授权仍需验证。"],"follow":"搜索文件名包含引号时 SQL 失败，怎么修？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-24","sourceRound":8,"sourceQuestion":2,"sourceRoundTitle":"预处理语句与参数绑定","referenceUrl":"https://dev.mysql.com/doc/refman/8.4/en/","answerMarkdown":"### 参考答案\n不能用参数任意绑定标识符；分页范围、排序选项和业务授权仍需验证。\n\n### 易错点\n不能用参数任意绑定标识符；分页范围、排序选项和业务授权仍需验证。\n\n### 继续追问\n搜索文件名包含引号时 SQL 失败，怎么修？"},{"id":"daily-2026-10-24-r08-q03","module":"MySQL","type":"场景题","title":"搜索文件名包含引号时 SQL 失败，怎么修？","prompt":"搜索文件名包含引号时 SQL 失败，怎么修？","promptMarkdown":"搜索文件名包含引号时 SQL 失败，怎么修？","answer":["优先用参数绑定处理字符串值，并审查字符集、转义和错误路径，不能手工替换几个字符。"],"pitfalls":["不能用参数任意绑定标识符；分页范围、排序选项和业务授权仍需验证。"],"follow":"搜索文件名包含引号时 SQL 失败，怎么修？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-24","sourceRound":8,"sourceQuestion":3,"sourceRoundTitle":"预处理语句与参数绑定","referenceUrl":"https://dev.mysql.com/doc/refman/8.4/en/","answerMarkdown":"### 参考答案\n优先用参数绑定处理字符串值，并审查字符集、转义和错误路径，不能手工替换几个字符。\n\n### 易错点\n不能用参数任意绑定标识符；分页范围、排序选项和业务授权仍需验证。\n\n### 继续追问\n搜索文件名包含引号时 SQL 失败，怎么修？"},{"id":"daily-2026-10-24-r08-q04","module":"MySQL","type":"代码题","title":"预处理语句与参数绑定：动手练习","prompt":"写按用户与文件名查询的预处理 SQL，说明两个参数的类型。","promptMarkdown":"写按用户与文件名查询的预处理 SQL，说明两个参数的类型。","answer":["预处理把 SQL 结构与参数值分开，绑定值不能改变 SQL 结构。表名、列名和排序方向通常不能作为普通参数绑定，应使用受控白名单。"],"pitfalls":["不能用参数任意绑定标识符；分页范围、排序选项和业务授权仍需验证。"],"follow":"搜索文件名包含引号时 SQL 失败，怎么修？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-24","sourceRound":8,"sourceQuestion":4,"sourceRoundTitle":"预处理语句与参数绑定","referenceUrl":"https://dev.mysql.com/doc/refman/8.4/en/","answerMarkdown":"### 参考答案\n预处理把 SQL 结构与参数值分开，绑定值不能改变 SQL 结构。表名、列名和排序方向通常不能作为普通参数绑定，应使用受控白名单。\n\n### 易错点\n不能用参数任意绑定标识符；分页范围、排序选项和业务授权仍需验证。\n\n### 示例\n```sql\nSELECT id,filename FROM files WHERE user_id=? AND filename=? AND status='active';\n```\n\n命令与配置用于隔离练习环境；先核对占位名称、权限、路径与工具版本。Docker 示例不代表已在你的服务中部署。\n\n### 继续追问\n搜索文件名包含引号时 SQL 失败，怎么修？"},{"id":"daily-2026-10-24-r08-q05","module":"MySQL","type":"场景题","title":"云盘用了 escape_string 就能声称没有任何注入风险吗？","prompt":"云盘用了 escape_string 就能声称没有任何注入风险吗？","promptMarkdown":"云盘用了 escape_string 就能声称没有任何注入风险吗？","answer":["转义依赖连接字符集、正确长度和所有输入路径；应逐项审查并优先参数化，同时防止动态标识符绕过和授权缺失。"],"pitfalls":["不能用参数任意绑定标识符；分页范围、排序选项和业务授权仍需验证。"],"follow":"搜索文件名包含引号时 SQL 失败，怎么修？","manual":true,"priority":false,"project":"云盘","sourceDate":"2026-10-24","sourceRound":8,"sourceQuestion":5,"sourceRoundTitle":"预处理语句与参数绑定","referenceUrl":"https://dev.mysql.com/doc/refman/8.4/en/","answerMarkdown":"### 参考答案\n转义依赖连接字符集、正确长度和所有输入路径；应逐项审查并优先参数化，同时防止动态标识符绕过和授权缺失。\n\n### 易错点\n不能用参数任意绑定标识符；分页范围、排序选项和业务授权仍需验证。\n\n### 继续追问\n搜索文件名包含引号时 SQL 失败，怎么修？"},{"id":"daily-2026-10-24-r09-q01","module":"Redis","type":"概念题","title":"大 key 与阻塞命令风险：关键机制","prompt":"请解释大 key 与阻塞命令风险的关键机制和适用边界。","promptMarkdown":"请解释大 key 与阻塞命令风险的关键机制和适用边界。","answer":["Redis 单次命令的工作量会影响事件处理延迟。大集合、批量删除或全量扫描都可能拖慢其他请求，需限制规模并用分批策略观察。"],"pitfalls":["它是渐进式遍历，COUNT 是提示，并非严格数量；数据变化时还要处理重复等语义。"],"follow":"运维脚本执行后接口尾延迟上升，先查什么？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-24","sourceRound":9,"sourceQuestion":1,"sourceRoundTitle":"大 key 与阻塞命令风险","referenceUrl":"https://redis.io/docs/latest/","answerMarkdown":"### 参考答案\nRedis 单次命令的工作量会影响事件处理延迟。大集合、批量删除或全量扫描都可能拖慢其他请求，需限制规模并用分批策略观察。\n\n### 易错点\n它是渐进式遍历，COUNT 是提示，并非严格数量；数据变化时还要处理重复等语义。\n\n### 继续追问\n运维脚本执行后接口尾延迟上升，先查什么？"},{"id":"daily-2026-10-24-r09-q02","module":"Redis","type":"概念题","title":"SCAN 完全不会影响延迟且返回数量固定吗？","prompt":"SCAN 完全不会影响延迟且返回数量固定吗？","promptMarkdown":"SCAN 完全不会影响延迟且返回数量固定吗？","answer":["它是渐进式遍历，COUNT 是提示，并非严格数量；数据变化时还要处理重复等语义。"],"pitfalls":["它是渐进式遍历，COUNT 是提示，并非严格数量；数据变化时还要处理重复等语义。"],"follow":"运维脚本执行后接口尾延迟上升，先查什么？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-24","sourceRound":9,"sourceQuestion":2,"sourceRoundTitle":"大 key 与阻塞命令风险","referenceUrl":"https://redis.io/docs/latest/","answerMarkdown":"### 参考答案\n它是渐进式遍历，COUNT 是提示，并非严格数量；数据变化时还要处理重复等语义。\n\n### 易错点\n它是渐进式遍历，COUNT 是提示，并非严格数量；数据变化时还要处理重复等语义。\n\n### 继续追问\n运维脚本执行后接口尾延迟上升，先查什么？"},{"id":"daily-2026-10-24-r09-q03","module":"Redis","type":"场景题","title":"运维脚本执行后接口尾延迟上升，先查什么？","prompt":"运维脚本执行后接口尾延迟上升，先查什么？","promptMarkdown":"运维脚本执行后接口尾延迟上升，先查什么？","answer":["关联慢日志、命令统计、键大小和脚本工作量，区分服务端阻塞与网络/客户端等待。"],"pitfalls":["它是渐进式遍历，COUNT 是提示，并非严格数量；数据变化时还要处理重复等语义。"],"follow":"运维脚本执行后接口尾延迟上升，先查什么？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-24","sourceRound":9,"sourceQuestion":3,"sourceRoundTitle":"大 key 与阻塞命令风险","referenceUrl":"https://redis.io/docs/latest/","answerMarkdown":"### 参考答案\n关联慢日志、命令统计、键大小和脚本工作量，区分服务端阻塞与网络/客户端等待。\n\n### 易错点\n它是渐进式遍历，COUNT 是提示，并非严格数量；数据变化时还要处理重复等语义。\n\n### 继续追问\n运维脚本执行后接口尾延迟上升，先查什么？"},{"id":"daily-2026-10-24-r09-q04","module":"Redis","type":"代码题","title":"大 key 与阻塞命令风险：动手练习","prompt":"只读分页扫描 lab 命名空间，不用 KEYS 遍历生产。","promptMarkdown":"只读分页扫描 lab 命名空间，不用 KEYS 遍历生产。","answer":["Redis 单次命令的工作量会影响事件处理延迟。大集合、批量删除或全量扫描都可能拖慢其他请求，需限制规模并用分批策略观察。"],"pitfalls":["它是渐进式遍历，COUNT 是提示，并非严格数量；数据变化时还要处理重复等语义。"],"follow":"运维脚本执行后接口尾延迟上升，先查什么？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-24","sourceRound":9,"sourceQuestion":4,"sourceRoundTitle":"大 key 与阻塞命令风险","referenceUrl":"https://redis.io/docs/latest/","answerMarkdown":"### 参考答案\nRedis 单次命令的工作量会影响事件处理延迟。大集合、批量删除或全量扫描都可能拖慢其他请求，需限制规模并用分批策略观察。\n\n### 易错点\n它是渐进式遍历，COUNT 是提示，并非严格数量；数据变化时还要处理重复等语义。\n\n### 示例\n```redis\nSCAN 0 MATCH lab:* COUNT 100\nSLOWLOG GET 10\nINFO commandstats\n```\n\n命令与配置用于隔离练习环境；先核对占位名称、权限、路径与工具版本。Docker 示例不代表已在你的服务中部署。\n\n### 继续追问\n运维脚本执行后接口尾延迟上升，先查什么？"},{"id":"daily-2026-10-24-r09-q05","module":"Redis","type":"场景题","title":"IM 在线用户集合越来越大，应该怎样查询？","prompt":"IM 在线用户集合越来越大，应该怎样查询？","promptMarkdown":"IM 在线用户集合越来越大，应该怎样查询？","answer":["优先按业务需要分页或维护合适索引，控制每次返回量；避免每次请求全量读取所有在线用户。"],"pitfalls":["它是渐进式遍历，COUNT 是提示，并非严格数量；数据变化时还要处理重复等语义。"],"follow":"运维脚本执行后接口尾延迟上升，先查什么？","manual":true,"priority":false,"project":"IM","sourceDate":"2026-10-24","sourceRound":9,"sourceQuestion":5,"sourceRoundTitle":"大 key 与阻塞命令风险","referenceUrl":"https://redis.io/docs/latest/","answerMarkdown":"### 参考答案\n优先按业务需要分页或维护合适索引，控制每次返回量；避免每次请求全量读取所有在线用户。\n\n### 易错点\n它是渐进式遍历，COUNT 是提示，并非严格数量；数据变化时还要处理重复等语义。\n\n### 继续追问\n运维脚本执行后接口尾延迟上升，先查什么？"},{"id":"daily-2026-10-24-r10-q01","module":"Nginx","type":"概念题","title":"请求体限制与上传故障分类：关键机制","prompt":"请解释请求体限制与上传故障分类的关键机制和适用边界。","promptMarkdown":"请解释请求体限制与上传故障分类的关键机制和适用边界。","answer":["client_max_body_size 约束请求正文大小；multipart 正文包含文件以外的边界和头部。代理、应用与客户端的限制和超时需要协调。"],"pitfalls":["整个 multipart 正文更大，Nginx 或客户端也可能有更低限制；须明确净文件和正文口径。"],"follow":"上传小文件成功，大文件直接 413，如何定位？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-24","sourceRound":10,"sourceQuestion":1,"sourceRoundTitle":"请求体限制与上传故障分类","referenceUrl":"https://nginx.org/en/docs/","answerMarkdown":"### 参考答案\nclient_max_body_size 约束请求正文大小；multipart 正文包含文件以外的边界和头部。代理、应用与客户端的限制和超时需要协调。\n\n### 易错点\n整个 multipart 正文更大，Nginx 或客户端也可能有更低限制；须明确净文件和正文口径。\n\n### 继续追问\n上传小文件成功，大文件直接 413，如何定位？"},{"id":"daily-2026-10-24-r10-q02","module":"Nginx","type":"概念题","title":"后端允许 10 MiB 就保证 10 MiB 文件能上传吗？","prompt":"后端允许 10 MiB 就保证 10 MiB 文件能上传吗？","promptMarkdown":"后端允许 10 MiB 就保证 10 MiB 文件能上传吗？","answer":["整个 multipart 正文更大，Nginx 或客户端也可能有更低限制；须明确净文件和正文口径。"],"pitfalls":["整个 multipart 正文更大，Nginx 或客户端也可能有更低限制；须明确净文件和正文口径。"],"follow":"上传小文件成功，大文件直接 413，如何定位？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-24","sourceRound":10,"sourceQuestion":2,"sourceRoundTitle":"请求体限制与上传故障分类","referenceUrl":"https://nginx.org/en/docs/","answerMarkdown":"### 参考答案\n整个 multipart 正文更大，Nginx 或客户端也可能有更低限制；须明确净文件和正文口径。\n\n### 易错点\n整个 multipart 正文更大，Nginx 或客户端也可能有更低限制；须明确净文件和正文口径。\n\n### 继续追问\n上传小文件成功，大文件直接 413，如何定位？"},{"id":"daily-2026-10-24-r10-q03","module":"Nginx","type":"场景题","title":"上传小文件成功，大文件直接 413，如何定位？","prompt":"上传小文件成功，大文件直接 413，如何定位？","promptMarkdown":"上传小文件成功，大文件直接 413，如何定位？","answer":["确认是入口代理还是应用返回，检查命中位置的正文限制并用边界大小测试。"],"pitfalls":["整个 multipart 正文更大，Nginx 或客户端也可能有更低限制；须明确净文件和正文口径。"],"follow":"上传小文件成功，大文件直接 413，如何定位？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-24","sourceRound":10,"sourceQuestion":3,"sourceRoundTitle":"请求体限制与上传故障分类","referenceUrl":"https://nginx.org/en/docs/","answerMarkdown":"### 参考答案\n确认是入口代理还是应用返回，检查命中位置的正文限制并用边界大小测试。\n\n### 易错点\n整个 multipart 正文更大，Nginx 或客户端也可能有更低限制；须明确净文件和正文口径。\n\n### 继续追问\n上传小文件成功，大文件直接 413，如何定位？"},{"id":"daily-2026-10-24-r10-q04","module":"Nginx","type":"代码题","title":"请求体限制与上传故障分类：动手练习","prompt":"阅读上传 location 的大小配置，说明为何不能盲目无限放大。","promptMarkdown":"阅读上传 location 的大小配置，说明为何不能盲目无限放大。","answer":["client_max_body_size 约束请求正文大小；multipart 正文包含文件以外的边界和头部。代理、应用与客户端的限制和超时需要协调。"],"pitfalls":["整个 multipart 正文更大，Nginx 或客户端也可能有更低限制；须明确净文件和正文口径。"],"follow":"上传小文件成功，大文件直接 413，如何定位？","manual":true,"priority":false,"project":"通用","sourceDate":"2026-10-24","sourceRound":10,"sourceQuestion":4,"sourceRoundTitle":"请求体限制与上传故障分类","referenceUrl":"https://nginx.org/en/docs/","answerMarkdown":"### 参考答案\nclient_max_body_size 约束请求正文大小；multipart 正文包含文件以外的边界和头部。代理、应用与客户端的限制和超时需要协调。\n\n### 易错点\n整个 multipart 正文更大，Nginx 或客户端也可能有更低限制；须明确净文件和正文口径。\n\n### 示例\n```nginx\nlocation /upload {\n    client_max_body_size 12m;\n    proxy_pass http://127.0.0.1:8080;\n}\n# 示例数值需与后端正文限制、资源预算协调\n```\n\n命令与配置用于隔离练习环境；先核对占位名称、权限、路径与工具版本。Docker 示例不代表已在你的服务中部署。\n\n### 继续追问\n上传小文件成功，大文件直接 413，如何定位？"},{"id":"daily-2026-10-24-r10-q05","module":"Nginx","type":"场景题","title":"云盘提高上传上限后还要核对什么？","prompt":"云盘提高上传上限后还要核对什么？","promptMarkdown":"云盘提高上传上限后还要核对什么？","answer":["正文内存、临时磁盘、FastCGI 进程并发和用户配额都可能成为瓶颈；仅改代理数值不能让系统支持任意大文件。"],"pitfalls":["整个 multipart 正文更大，Nginx 或客户端也可能有更低限制；须明确净文件和正文口径。"],"follow":"上传小文件成功，大文件直接 413，如何定位？","manual":true,"priority":false,"project":"云盘","sourceDate":"2026-10-24","sourceRound":10,"sourceQuestion":5,"sourceRoundTitle":"请求体限制与上传故障分类","referenceUrl":"https://nginx.org/en/docs/","answerMarkdown":"### 参考答案\n正文内存、临时磁盘、FastCGI 进程并发和用户配额都可能成为瓶颈；仅改代理数值不能让系统支持任意大文件。\n\n### 易错点\n整个 multipart 正文更大，Nginx 或客户端也可能有更低限制；须明确净文件和正文口径。\n\n### 继续追问\n上传小文件成功，大文件直接 413，如何定位？"},{"id":"daily-2026-10-24-r11-q01","module":"项目追问","type":"概念题","title":"IM：背压与慢客户端：关键机制","prompt":"请解释IM：背压与慢客户端的关键机制和适用边界。","promptMarkdown":"请解释IM：背压与慢客户端的关键机制和适用边界。","answer":["接收速度长期低于发送速度时，队列会增长；应限制每连接与全局排队量，区分可丢弃通知和需要可靠恢复的消息。"],"pitfalls":["内存耗尽会扩大故障，必须有容量、超时和可恢复的业务策略。"],"follow":"少数慢客户端拖累整节点，如何隔离？","manual":true,"priority":false,"project":"IM","sourceDate":"2026-10-24","sourceRound":11,"sourceQuestion":1,"sourceRoundTitle":"IM：背压与慢客户端","referenceUrl":"https://github.com/qzshen219-pixel/im-system","answerMarkdown":"### 参考答案\n接收速度长期低于发送速度时，队列会增长；应限制每连接与全局排队量，区分可丢弃通知和需要可靠恢复的消息。\n\n### 易错点\n内存耗尽会扩大故障，必须有容量、超时和可恢复的业务策略。\n\n### 继续追问\n少数慢客户端拖累整节点，如何隔离？"},{"id":"daily-2026-10-24-r11-q02","module":"项目追问","type":"概念题","title":"队列无限增大就能保证不丢消息吗？","prompt":"队列无限增大就能保证不丢消息吗？","promptMarkdown":"队列无限增大就能保证不丢消息吗？","answer":["内存耗尽会扩大故障，必须有容量、超时和可恢复的业务策略。"],"pitfalls":["内存耗尽会扩大故障，必须有容量、超时和可恢复的业务策略。"],"follow":"少数慢客户端拖累整节点，如何隔离？","manual":true,"priority":false,"project":"IM","sourceDate":"2026-10-24","sourceRound":11,"sourceQuestion":2,"sourceRoundTitle":"IM：背压与慢客户端","referenceUrl":"https://github.com/qzshen219-pixel/im-system","answerMarkdown":"### 参考答案\n内存耗尽会扩大故障，必须有容量、超时和可恢复的业务策略。\n\n### 易错点\n内存耗尽会扩大故障，必须有容量、超时和可恢复的业务策略。\n\n### 继续追问\n少数慢客户端拖累整节点，如何隔离？"},{"id":"daily-2026-10-24-r11-q03","module":"项目追问","type":"场景题","title":"少数慢客户端拖累整节点，如何隔离？","prompt":"少数慢客户端拖累整节点，如何隔离？","promptMarkdown":"少数慢客户端拖累整节点，如何隔离？","answer":["观察队列字节和最老等待时间，限制单连接资源，关键消息由持久化与补拉恢复。"],"pitfalls":["内存耗尽会扩大故障，必须有容量、超时和可恢复的业务策略。"],"follow":"少数慢客户端拖累整节点，如何隔离？","manual":true,"priority":false,"project":"IM","sourceDate":"2026-10-24","sourceRound":11,"sourceQuestion":3,"sourceRoundTitle":"IM：背压与慢客户端","referenceUrl":"https://github.com/qzshen219-pixel/im-system","answerMarkdown":"### 参考答案\n观察队列字节和最老等待时间，限制单连接资源，关键消息由持久化与补拉恢复。\n\n### 易错点\n内存耗尽会扩大故障，必须有容量、超时和可恢复的业务策略。\n\n### 继续追问\n少数慢客户端拖累整节点，如何隔离？"},{"id":"daily-2026-10-24-r11-q04","module":"项目追问","type":"代码题","title":"IM：背压与慢客户端：动手练习","prompt":"写背压策略决策表，区分正文与正在输入事件。","promptMarkdown":"写背压策略决策表，区分正文与正在输入事件。","answer":["接收速度长期低于发送速度时，队列会增长；应限制每连接与全局排队量，区分可丢弃通知和需要可靠恢复的消息。"],"pitfalls":["内存耗尽会扩大故障，必须有容量、超时和可恢复的业务策略。"],"follow":"少数慢客户端拖累整节点，如何隔离？","manual":true,"priority":false,"project":"IM","sourceDate":"2026-10-24","sourceRound":11,"sourceQuestion":4,"sourceRoundTitle":"IM：背压与慢客户端","referenceUrl":"https://github.com/qzshen219-pixel/im-system","answerMarkdown":"### 参考答案\n接收速度长期低于发送速度时，队列会增长；应限制每连接与全局排队量，区分可丢弃通知和需要可靠恢复的消息。\n\n### 易错点\n内存耗尽会扩大故障，必须有容量、超时和可恢复的业务策略。\n\n### 示例\n```bash\n# typing：允许合并或丢弃旧事件\n# message：保留业务记录，不能仅内存无痕丢弃\n# 超过连接预算：限速或断开，并支持恢复\n```\n\n命令与配置用于隔离练习环境；先核对占位名称、权限、路径与工具版本。Docker 示例不代表已在你的服务中部署。\n\n### 继续追问\n少数慢客户端拖累整节点，如何隔离？"},{"id":"daily-2026-10-24-r11-q05","module":"项目追问","type":"场景题","title":"IM 断开慢连接前如何避免重复投递与丢失感知？","prompt":"IM 断开慢连接前如何避免重复投递与丢失感知？","promptMarkdown":"IM 断开慢连接前如何避免重复投递与丢失感知？","answer":["明确最后确认水位和未确认消息范围，重连按业务 ID 去重与补拉；断开本身不是可靠性策略的全部。"],"pitfalls":["内存耗尽会扩大故障，必须有容量、超时和可恢复的业务策略。"],"follow":"少数慢客户端拖累整节点，如何隔离？","manual":true,"priority":false,"project":"IM","sourceDate":"2026-10-24","sourceRound":11,"sourceQuestion":5,"sourceRoundTitle":"IM：背压与慢客户端","referenceUrl":"https://github.com/qzshen219-pixel/im-system","answerMarkdown":"### 参考答案\n明确最后确认水位和未确认消息范围，重连按业务 ID 去重与补拉；断开本身不是可靠性策略的全部。\n\n### 易错点\n内存耗尽会扩大故障，必须有容量、超时和可恢复的业务策略。\n\n### 继续追问\n少数慢客户端拖累整节点，如何隔离？"},{"id":"daily-2026-10-24-r12-q01","module":"项目追问","type":"概念题","title":"云盘：文件名、路径与响应头：关键机制","prompt":"请解释云盘：文件名、路径与响应头的关键机制和适用边界。","promptMarkdown":"请解释云盘：文件名、路径与响应头的关键机制和适用边界。","answer":["原始文件名是显示元数据，不应直接成为可信存储路径。下载响应头需正确编码名字，并过滤控制字符；路径授权与内容定位要分开。"],"pitfalls":["编码、符号链接与检查后替换等问题仍存在，应使用受控目录、可靠路径约束与明确威胁模型。"],"follow":"中文文件名下载乱码或换行污染响应，如何排查？","manual":true,"priority":false,"project":"云盘","sourceDate":"2026-10-24","sourceRound":12,"sourceQuestion":1,"sourceRoundTitle":"云盘：文件名、路径与响应头","referenceUrl":"https://github.com/qzshen219-pixel/distributed-cloud-disk","answerMarkdown":"### 参考答案\n原始文件名是显示元数据，不应直接成为可信存储路径。下载响应头需正确编码名字，并过滤控制字符；路径授权与内容定位要分开。\n\n### 易错点\n编码、符号链接与检查后替换等问题仍存在，应使用受控目录、可靠路径约束与明确威胁模型。\n\n### 继续追问\n中文文件名下载乱码或换行污染响应，如何排查？"},{"id":"daily-2026-10-24-r12-q02","module":"项目追问","type":"概念题","title":"把 ../ 从字符串删掉就杜绝路径穿越了吗？","prompt":"把 ../ 从字符串删掉就杜绝路径穿越了吗？","promptMarkdown":"把 ../ 从字符串删掉就杜绝路径穿越了吗？","answer":["编码、符号链接与检查后替换等问题仍存在，应使用受控目录、可靠路径约束与明确威胁模型。"],"pitfalls":["编码、符号链接与检查后替换等问题仍存在，应使用受控目录、可靠路径约束与明确威胁模型。"],"follow":"中文文件名下载乱码或换行污染响应，如何排查？","manual":true,"priority":false,"project":"云盘","sourceDate":"2026-10-24","sourceRound":12,"sourceQuestion":2,"sourceRoundTitle":"云盘：文件名、路径与响应头","referenceUrl":"https://github.com/qzshen219-pixel/distributed-cloud-disk","answerMarkdown":"### 参考答案\n编码、符号链接与检查后替换等问题仍存在，应使用受控目录、可靠路径约束与明确威胁模型。\n\n### 易错点\n编码、符号链接与检查后替换等问题仍存在，应使用受控目录、可靠路径约束与明确威胁模型。\n\n### 继续追问\n中文文件名下载乱码或换行污染响应，如何排查？"},{"id":"daily-2026-10-24-r12-q03","module":"项目追问","type":"场景题","title":"中文文件名下载乱码或换行污染响应，如何排查？","prompt":"中文文件名下载乱码或换行污染响应，如何排查？","promptMarkdown":"中文文件名下载乱码或换行污染响应，如何排查？","answer":["检查 Content-Disposition 的编码和控制字符处理，测试引号、中文、长名与换行。"],"pitfalls":["编码、符号链接与检查后替换等问题仍存在，应使用受控目录、可靠路径约束与明确威胁模型。"],"follow":"中文文件名下载乱码或换行污染响应，如何排查？","manual":true,"priority":false,"project":"云盘","sourceDate":"2026-10-24","sourceRound":12,"sourceQuestion":3,"sourceRoundTitle":"云盘：文件名、路径与响应头","referenceUrl":"https://github.com/qzshen219-pixel/distributed-cloud-disk","answerMarkdown":"### 参考答案\n检查 Content-Disposition 的编码和控制字符处理，测试引号、中文、长名与换行。\n\n### 易错点\n编码、符号链接与检查后替换等问题仍存在，应使用受控目录、可靠路径约束与明确威胁模型。\n\n### 继续追问\n中文文件名下载乱码或换行污染响应，如何排查？"},{"id":"daily-2026-10-24-r12-q04","module":"项目追问","type":"代码题","title":"云盘：文件名、路径与响应头：动手练习","prompt":"列出下载文件名回归样本和检查点，不使用真实敏感文件。","promptMarkdown":"列出下载文件名回归样本和检查点，不使用真实敏感文件。","answer":["原始文件名是显示元数据，不应直接成为可信存储路径。下载响应头需正确编码名字，并过滤控制字符；路径授权与内容定位要分开。"],"pitfalls":["编码、符号链接与检查后替换等问题仍存在，应使用受控目录、可靠路径约束与明确威胁模型。"],"follow":"中文文件名下载乱码或换行污染响应，如何排查？","manual":true,"priority":false,"project":"云盘","sourceDate":"2026-10-24","sourceRound":12,"sourceQuestion":4,"sourceRoundTitle":"云盘：文件名、路径与响应头","referenceUrl":"https://github.com/qzshen219-pixel/distributed-cloud-disk","answerMarkdown":"### 参考答案\n原始文件名是显示元数据，不应直接成为可信存储路径。下载响应头需正确编码名字，并过滤控制字符；路径授权与内容定位要分开。\n\n### 易错点\n编码、符号链接与检查后替换等问题仍存在，应使用受控目录、可靠路径约束与明确威胁模型。\n\n### 示例\n```bash\n# 中文：报告.txt\n# 引号：a\"b.txt\n# 路径样式：../demo.txt\n# 控制字符：必须拒绝或安全编码，不能原样拼接响应头\n```\n\n命令与配置用于隔离练习环境；先核对占位名称、权限、路径与工具版本。Docker 示例不代表已在你的服务中部署。\n\n### 继续追问\n中文文件名下载乱码或换行污染响应，如何排查？"},{"id":"daily-2026-10-24-r12-q05","module":"项目追问","type":"场景题","title":"云盘存储 ID 与用户传来的路径应该怎样关联？","prompt":"云盘存储 ID 与用户传来的路径应该怎样关联？","promptMarkdown":"云盘存储 ID 与用户传来的路径应该怎样关联？","answer":["先查可信元数据并验证权限，再用服务端受控存储 ID 定位内容；不接受客户端指定任意服务器路径。"],"pitfalls":["编码、符号链接与检查后替换等问题仍存在，应使用受控目录、可靠路径约束与明确威胁模型。"],"follow":"中文文件名下载乱码或换行污染响应，如何排查？","manual":true,"priority":false,"project":"云盘","sourceDate":"2026-10-24","sourceRound":12,"sourceQuestion":5,"sourceRoundTitle":"云盘：文件名、路径与响应头","referenceUrl":"https://github.com/qzshen219-pixel/distributed-cloud-disk","answerMarkdown":"### 参考答案\n先查可信元数据并验证权限，再用服务端受控存储 ID 定位内容；不接受客户端指定任意服务器路径。\n\n### 易错点\n编码、符号链接与检查后替换等问题仍存在，应使用受控目录、可靠路径约束与明确威胁模型。\n\n### 继续追问\n中文文件名下载乱码或换行污染响应，如何排查？"}];const ids=new Set(window.QUESTION_BANK.map(q=>q.id));for(const q of added){if(!ids.has(q.id)){window.QUESTION_BANK.push(q);ids.add(q.id);}}})();
